from pathlib import Path
import base64,json
P=Path(__file__).parent;m=json.loads((P/'manifest.json').read_text())
def uri(n):return 'data:image/png;base64,'+base64.b64encode((P/n).read_bytes()).decode()
s='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Finch cutout control proof</title><style>body{font:17px/1.5 system-ui;background:#172c2a;color:#f4eedb;max-width:1000px;margin:auto;padding:24px}canvas,img{max-width:100%;image-rendering:pixelated;background:#e1dbc8}button,input{font:inherit}strong{color:#ffbd99}pre{white-space:pre-wrap;font-size:13px}label{display:inline-block;margin:10px}</style><h1>Fixed body, cutout head: engineering proof</h1><p><strong>Existing pixels + deterministic head transform. Zero new generated drawings. Not approved animation.</strong> Rough head/neck mask and missing underpaint can expose gaps; no preening or walking anatomy is demonstrated.</p><canvas id="view" width="1024" height="1024" style="width:512px"></canvas><div><button id="play">Pause</button><label>Facing <select id="face"><option value="1">right</option><option value="-1">left mirrored</option></select></label><label>Phase <input id="phase" type="range" min="0" max="4" value="0"></label></div><pre id="metrics">Loading retained pixels…</pre><p>The fixed body/feet region y≥600 is copied byte-for-byte from the retained neutral. This is a property of the compositor, not a promise from diffusion. Source scale and the two heuristic foot neighborhoods stay fixed. Full biological identity, neck seam, occlusion and motion acceptance remain open.</p><h2>Conditioning scaffold</h2><p>Black-on-white exterior contour,512px. This is a rough authored cutout guide, not a depth map, semantic segmentation model input or an approved bird-pose drawing. Interior wing/bill/neck linework still needs art review.</p>'''
s+='<img width="256" src="'+uri('outline-01.png')+'"><p>Current source proof exceeds the inspected app export profile (1024px source vs256max and decoded-pixel budget). No app manifest/admission is claimed.</p>'
s+='<script>const config='+json.dumps(m)+';const sourceURL='+json.dumps(uri('source-neutral.png'))+';const maskURL='+json.dumps(uri('head-mask.png'))+';</script>'
s+='''<script>
(async()=>{const N=1024,canvas=document.getElementById('view'),ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.imageSmoothingEnabled=false;const load=src=>new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src});const [src,maskImage]=await Promise.all([load(sourceURL),load(maskURL)]);const off=document.createElement('canvas');off.width=off.height=N;const oc=off.getContext('2d',{willReadFrequently:true});oc.drawImage(src,0,0);const original=oc.getImageData(0,0,N,N);oc.clearRect(0,0,N,N);oc.drawImage(maskImage,0,0);const mask=oc.getImageData(0,0,N,N).data;const body=new Uint8ClampedArray(original.data);for(let p=0;p<N*N;p++)if(mask[p*4]>0)body.fill(0,p*4,p*4+4);let playing=true,phase=0,last=0;
function render(k){const angle=config.frames[k].angleRadians,c=Math.cos(angle),s=Math.sin(angle),out=new Uint8ClampedArray(body),cx=560,cy=516;if(angle===0)out.set(original.data);else for(let y=0;y<600;y++)for(let x=0;x<N;x++){const sx=Math.floor(c*(x-cx)+s*(y-cy)+cx+.5),sy=Math.floor(-s*(x-cx)+c*(y-cy)+cy+.5);if(sx<0||sy<0||sx>=N||sy>=N)continue;const i=(sy*N+sx)*4,j=(y*N+x)*4;if(mask[i]&&original.data[i+3])out.set(original.data.subarray(i,i+4),j);}out.set(original.data.subarray(600*N*4),600*N*4);let changed=0;for(let i=600*N*4;i<out.length;i+=4)if(out[i]!==original.data[i]||out[i+1]!==original.data[i+1]||out[i+2]!==original.data[i+2]||out[i+3]!==original.data[i+3])changed++;oc.putImageData(new ImageData(out,N,N),0,0);ctx.clearRect(0,0,N,N);ctx.save();if(document.getElementById('face').value==='-1'){ctx.translate(N,0);ctx.scale(-1,1);}ctx.drawImage(off,0,0);ctx.restore();document.getElementById('phase').value=k;document.getElementById('metrics').textContent=JSON.stringify({phase:k,headRotationRadians:angle,protectedRGBAChangedPixels:changed,bodyScale:1,newGeneratedDrawings:0,artAccepted:false,physicalScaleApproved:false},null,2);window.proofLast={phase:k,changed,angle,bodyScale:1};return window.proofLast;}
window.proofRender=render;document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'Pause':'Play'};document.getElementById('phase').oninput=e=>{playing=false;phase=+e.target.value;render(phase)};document.getElementById('face').onchange=()=>render(phase);function step(t){if(playing&&t-last>=160){phase=(phase+1)%5;render(phase);last=t;}requestAnimationFrame(step);}render(0);window.proofReady=true;requestAnimationFrame(step);})();
</script>'''
(P/'review.html').write_text(s);print(P/'review.html')
